require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$eventId=(int)($_GET['id']??$_POST['id']??0);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf_token($_POST['csrf_token']??'')){$action=$_POST['action']??'';if($action==='department'){$code=strtoupper(trim($_POST['department_code']??''));$name=trim($_POST['department_name']??'');if($code&&$name)pg_query_params($conn,'INSERT INTO departments(code,name) VALUES($1,$2) ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name',[$code,$name]);redirect('details.php?id='.$eventId);}if($action==='save'){$department=(int)($_POST['department_id']??0)?:null;$type=trim($_POST['event_type']??'Program');$organizer=trim($_POST['organizer']??'');$year=trim($_POST['school_year']??'');$semester=trim($_POST['semester']??'');$photo=isset($_POST['require_photo_evidence'])?'true':'false';$meal=isset($_POST['meal_event'])?'true':'false';$everyone=isset($_POST['everyone_present_at_timeout'])?'true':'false';$fines=isset($_POST['fines_enabled'])?'true':'false';$absence=max(0,(float)($_POST['absence_fine']??0));$missing=max(0,(float)($_POST['missing_scan_fine']??0));pg_query_params($conn,'UPDATE events SET department_id=$1,event_type=$2,organizer=$3,school_year=$4,semester=$5,require_photo_evidence=$6,meal_event=$7,everyone_present_at_timeout=$8,fines_enabled=$9,absence_fine=$10,missing_scan_fine=$11,updated_at=NOW() WHERE id=$12',[$department,$type,$organizer,$year,$semester,$photo,$meal,$everyone,$fines,$absence,$missing,$eventId]);foreach(['morning','afternoon','evening'] as $name){$prefix=$name.'_';$values=[];foreach(['time_in_start','time_in_end','time_out_start','time_out_end'] as $field)$values[]=trim($_POST[$prefix.$field]??'')?:null;$status=$_POST[$prefix.'status']??'draft';pg_query_params($conn,'INSERT INTO event_sessions(event_id,session_name,time_in_start,time_in_end,time_out_start,time_out_end,status) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(event_id,session_name) DO UPDATE SET time_in_start=EXCLUDED.time_in_start,time_in_end=EXCLUDED.time_in_end,time_out_start=EXCLUDED.time_out_start,time_out_end=EXCLUDED.time_out_end,status=EXCLUDED.status',[$eventId,$name,...$values,$status]);}audit_log($conn,'event_rules_updated','event',$eventId);redirect('details.php?id='.$eventId.'&saved=1');}}
$r=pg_query_params($conn,'SELECT * FROM events WHERE id=$1',[$eventId]);$event=$r&&pg_num_rows($r)?pg_fetch_assoc($r):null;if(!$event){http_response_code(404);exit('Event not found.');}foreach(['morning','afternoon','evening'] as $name)pg_query_params($conn,'INSERT INTO event_sessions(event_id,session_name) VALUES($1,$2) ON CONFLICT DO NOTHING',[$eventId,$name]);$sessions=[];$sr=pg_query_params($conn,'SELECT * FROM event_sessions WHERE event_id=$1 ORDER BY id',[$eventId]);while($s=pg_fetch_assoc($sr))$sessions[$s['session_name']]=$s;$departments=pg_query($conn,'SELECT * FROM departments WHERE is_active=TRUE ORDER BY name');admin_page_start('Event Sessions & Rules','events');?>
<div class="hero"><div><h2><?=h($event['title'])?></h2><p>Department folder, event rules, session schedules, photo evidence, and fines.</p></div><a class="btn secondary" href="index.php"><i class="fas fa-arrow-left"></i> Events</a></div><?php if(isset($_GET['saved'])):?><div class="alert">Event configuration saved.</div><?php endif;?>
<div class="card"><h3>Department folder</h3><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$eventId?>"><input type="hidden" name="action" value="department"><div class="field"><label>Department code</label><input name="department_code" placeholder="CBIT"></div><div class="field"><label>Department name</label><input name="department_name" placeholder="College of Business and Information Technology"></div><div class="field full"><button class="btn secondary">Add / Update Department</button></div></form></div>
<form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$eventId?>"><input type="hidden" name="action" value="save"><div class="card"><h3>Event classification</h3><div class="form-grid"><div class="field"><label>Department folder</label><select name="department_id"><option value="">School-wide</option><?php if($departments):while($d=pg_fetch_assoc($departments)):?><option value="<?=(int)$d['id']?>" <?=(int)$event['department_id']===(int)$d['id']?'selected':''?>><?=h($d['code'].' — '.$d['name'])?></option><?php endwhile;endif;?></select></div><div class="field"><label>Event type</label><input name="event_type" value="<?=h($event['event_type'])?>"></div><div class="field"><label>Organizer</label><input name="organizer" value="<?=h($event['organizer'])?>"></div><div class="field"><label>School year</label><input name="school_year" value="<?=h($event['school_year'])?>" placeholder="2026-2027"></div><div class="field full"><label>Semester</label><select name="semester"><option value="">Not specified</option><?php foreach(['First Semester','Second Semester','Summer'] as $sem):?><option <?=$event['semester']===$sem?'selected':''?>><?=$sem?></option><?php endforeach;?></select></div></div></div>
<div class="card"><h3>Attendance rules</h3><div class="choices"><label class="choice"><input type="checkbox" name="require_photo_evidence" <?=$event['require_photo_evidence']==='t'?'checked':''?>><span><strong>Photo evidence and face-presence check required</strong><br><span class="help">Every session scan captures compressed proof and checks for a visible face on-device.</span></span></label><label class="choice"><input type="checkbox" name="meal_event" <?=$event['meal_event']==='t'?'checked':''?>><span><strong>Meal event</strong><br><span class="help">Marks this event for meal attendance reporting.</span></span></label><label class="choice"><input type="checkbox" name="everyone_present_at_timeout" <?=$event['everyone_present_at_timeout']==='t'?'checked':''?>><span><strong>Everyone present at time-out</strong><br><span class="help">Students do not need a separate time-out scan.</span></span></label><label class="choice"><input type="checkbox" name="fines_enabled" <?=$event['fines_enabled']==='t'?'checked':''?>><span><strong>Fines for missed attendance</strong></span></label></div><div class="form-grid" style="margin-top:16px"><div class="field"><label>Absence fine</label><input type="number" min="0" step="0.01" name="absence_fine" value="<?=h($event['absence_fine'])?>"></div><div class="field"><label>Missing scan fine</label><input type="number" min="0" step="0.01" name="missing_scan_fine" value="<?=h($event['missing_scan_fine'])?>"></div></div></div>
<?php foreach(['morning','afternoon','evening'] as $name):$s=$sessions[$name];?><div class="card"><h3><i class="fas fa-clock"></i> <?=h(ucfirst($name))?> Session</h3><div class="form-grid"><div class="field"><label>Time-in opens</label><input type="datetime-local" name="<?=$name?>_time_in_start" value="<?=h($s['time_in_start']?date('Y-m-d\TH:i',strtotime($s['time_in_start'])):'')?>"></div><div class="field"><label>Time-in closes</label><input type="datetime-local" name="<?=$name?>_time_in_end" value="<?=h($s['time_in_end']?date('Y-m-d\TH:i',strtotime($s['time_in_end'])):'')?>"></div><div class="field"><label>Time-out opens</label><input type="datetime-local" name="<?=$name?>_time_out_start" value="<?=h($s['time_out_start']?date('Y-m-d\TH:i',strtotime($s['time_out_start'])):'')?>"></div><div class="field"><label>Time-out closes</label><input type="datetime-local" name="<?=$name?>_time_out_end" value="<?=h($s['time_out_end']?date('Y-m-d\TH:i',strtotime($s['time_out_end'])):'')?>"></div><div class="field full"><label>Status</label><select name="<?=$name?>_status"><?php foreach(['draft','open','closed'] as $status):?><option value="<?=$status?>" <?=$s['status']===$status?'selected':''?>><?=h(ucfirst($status))?></option><?php endforeach;?></select></div></div></div><?php endforeach;?><button class="btn" style="margin-bottom:30px"><i class="fas fa-save"></i> Save Event Rules and Sessions</button></form><?php admin_page_end();?>
